-- 0291 limpiar 【turnXsearchY】 de descripciones misterioso
UPDATE entidades SET descripcion='Mayor enclave templario de la Península. Leyendas sobre el tesoro templario más grande de la Cristiandad escondido en sus muros, símbolos esotéricos y un supuesto pasadizo que lo conecta con el castillo de Cornatel. Atractivos: Castillo de los Templarios (siglo XII), casco histórico, Museo del Bierzo.' WHERE codigo_ine='24115' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La leyenda de la princesa musulmana que, traicionada por enamorarse de un noble cristiano, fue convertida en gallina por su padre brujo. Cada 23 de abril su sombra recorre las calles cacereñas próximas al palacio. El Parador acumula testimonios de presencias. Atractivos: Parador de Cáceres (antiguos palacios góticos), casco antiguo Patrimonio UNESCO.' WHERE codigo_ine='10037' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='En 1550 se manifestaron extrañas luces y una aparición divina en la Puerta del Lobo. En una cueva aparecieron formas blancas, luces y una figura infantil misteriosa. Atractivos: Casco renacentista (Patrimonio UNESCO), Universidad antigua, Puerta del Lobo.' WHERE codigo_ine='24010' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Desde 1971, en la cocina de la casa de María Gómez Cámara empezaron a aparecer —y reaparecer tras ser picadas— manchas con forma de rostros humanos en el suelo de cemento. Es uno de los casos paranormales más famosos del mundo y la casa sigue siendo visitable en el pueblo. Atractivos: Casa de "Las Caras", Museo de Bélmez.' WHERE codigo_ine='24018' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Tras la expulsión morisca fue repoblado por familias gallegas que trajeron el culto a las meigas. Cada calle tiene su historia mágica. Símbolos esotéricos y figuras repartidas por el pueblo. Atractivos: "Pueblo de las Brujas" de la Alpujarra, Museo de la Brujería, Casa de Baba Yaga, Casa de Hansel y Gretel, Fuente de los Cántaros, Cueva del Ojo de Guayota, Fuente del Dragón.' WHERE codigo_ine='18176' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Tildado de "pueblo maldito", sus calles han sido escenario de numerosas leyendas, entre ellas la del jinete sombrío que aparece cabalgando las noches de luna llena por la zona alta del pueblo. Atractivos: Casco histórico, vistas del Guadiana.' WHERE codigo_ine='22006' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Existen leyendas locales de "cortijos malditos" y apariciones espectrales en las sierras circundantes, ligadas a un sustrato de brujería rural que sobrevivió hasta el siglo XX. Atractivos: Gruta de las Maravillas, Sierra de Aracena.' WHERE codigo_ine='22004' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Su leyenda fundacional es en sí un misterio: un pastor desaparece misteriosamente y en el lugar donde se le vio por última vez brota un manantial que da origen al pueblo. Atractivos: Plaza de los Toros, iglesia de San Jerónimo.' WHERE codigo_ine='21034' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El fantasma de doña Blanca en la plaza de Orive (leyenda del noble Carlos Ucel y su hija blanca y hermosa). El fantasma de la Mezquita (alojo nocturno). Medina Azahara con leyendas de amor y poder. La Facultad de Derecho, sobre un antiguo hospital psiquiátrico, es uno de los edificios con más actividad paranormal de Andalucía. Atractivos: Mezquita-Catedral, Medina Azahara, Facultad de Derecho, barrio de la Judería, Plaza de Orive.' WHERE codigo_ine='14021' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El Teatro Cervantes guarda la historia de Conchita Robles, actriz asesinada en 1922 cuyas apariciones siguen reportándose. Además, en la provincia existieron dos casos de apariciones marianas y apariciones ligadas al accidente ferroviario de Fiñana en 1943. Atractivos: Teatro Cervantes, Alcazaba, casco histórico.' WHERE codigo_ine='04004' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Según la leyenda, en sus muros falleció el conde Don Julián y está enterrado el "mayor traidor de España". Numerosos visitantes reportan la aparición del fantasma del conde y de doña Violante de Luna, sobrina del Papa Luna, cuya tumba nunca se halló. Atractivos: Castillo de Loarre (el románico mejor conservado de Europa).' WHERE codigo_ine='22149' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las "tierras de brujas" más documentadas de la Sierra de Albarracín. La leyenda del pastor y las brujas de Jabaloyas cuenta que descendían volando sobre escobas para robar el vino de las bodegas de Frías de Albarracín. Atractivos: Monte Javalón, Ermita de la Virgen de Trinidad, iglesia de la Asunción.' WHERE codigo_ine='44127' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Escenario complementario de la leyenda de las brujas de Jabaloyas. La tradición oral mantiene viva la historia del "Tío Candelas" y su bodega vigilada. Atractivos: Bodegas tradicionales, casco urbano.' WHERE codigo_ine='44109' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los pueblos más mágicos de España, con leyendas de apariciones en sus callejuelas, una abundante tradición de brujería en la sierra y un caso documentado de experiencia paranormal en el casco urbano. Atractivos: Murallas, casco medieval, Plaza Mayor.' WHERE codigo_ine='43001' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Vigía del Camino de Santiago desde el siglo IX. Sus murallas acumulan leyendas de prisioneros, nobles y reyes, y son frecuentes las rutas nocturnas de misterio. Atractivos: Castillo de Castrojeriz, Convento de San Antón, excolegiata de Nuestra Señora del Manzano.' WHERE codigo_ine='09091' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='"En Calatañazor perdió Almanzor el tambor". Pueblo detenido en el tiempo donde, según la leyenda, cayó el invencible caudillo musulmán. El ambiente medieval invita a rutas de leyenda. Atractivos: Villa medieval amurallada, castillo, plazuelta del árbol torcido.' WHERE codigo_ine='42046' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='En lo alto del cerro de La Muela aún se siente, según los visitantes, "la fuerza de un pueblo que resistió al Imperio Romano". Numancia es un lugar cargado de energía histórica y leyendas de sacrificio colectivo. Atractivos: Numancia, yacimiento celtíbero.' WHERE codigo_ine='42094' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Considerado durante siglos un foco de brujería, aparece recogido en las crónicas de cazas de brujas de la provincia, junto con otros pueblos sorianos de tradición esotérica. Atractivos: Casco urbano serrano, paisaje de la Sierra de Urbión.' WHERE codigo_ine='42029' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La leyenda del fantasma de Masegoso cuenta que el pueblo entero desapareció tras un envenenamiento por envidia. Es uno de los enigmas rurales de Soria. Atractivos: Ruinas del pueblo despoblado.' WHERE codigo_ine='19127' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Cuna de la leyenda del Hombre Pez de Liérganes, el ser mitad hombre mitad pez que, según la tradición del siglo XVIII, fue visto en distintas costas europeas. El pueblo tiene un marcado carácter de leyenda. Atractivos: Puente Romano, Centro de Interpretación del Hombre Pez, casonas nobiliarias.' WHERE codigo_ine='39037' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Capital de Liébana, tierra de ojáncanos, anjanas y leyendas de tesoros ocultos. Existe la leyenda de la "Mansión de los Espíritus", una casona habitada por almas perdidas. Atractivos: Torre del Infantado, casco histórico, Picos de Europa.' WHERE codigo_ine='39055' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El castillo se levantó sobre una ermita del siglo IX y aún conserva una necrópolis en su patio. Existe un sainete teatral tradicional, "El fantasma del Castillo de Argüeso", basado en la traición de Don Fernando de Mier. Atractivos: Castillo de Argüeso, necrópolis del patio de armas.' WHERE codigo_ine='39032' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Casa de los Bayón fue escenario, a comienzos del siglo XX, de uno de los casos de poltergeist más famosos de España, documentado incluso con intervención de la Guardia Civil. Es considerada una de las casas rurales más embrujadas del país. Atractivos: Casa del Bayón (Rayán), valle minero.' WHERE codigo_ine='90637' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='En abril de 1854 todos los habitantes de Mengollo aparecieron muertos sin signos de violencia. Es la "leyenda del pueblo fantasma de Asturias", uno de los enigmas sin resolver de la región. Atractivos: Pueblo despoblado de Mengollo, valle del Quirós.' WHERE codigo_ine='33053' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El valle fue, según la leyenda, la prisión donde un hidalgo cumplió cadena perpetua por asesinar al cura del pueblo por orden de su señor. Es una ruta de misterio destacada. Atractivos: Valle del Desterrado, cascada de Seimeira.' WHERE codigo_ine='33062' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Según la tradición, la noche de San Juan aparece un hada encantada en la cascada de la Pena do Encanto para hechizar a quien la vea. Una de las rutas mágicas más señaladas de Asturias. Atractivos: Ruta de la Pena do Encanto, cascada.' WHERE codigo_ine='33063' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Crónica de brujería marinera: si los marineros se cruzaban con una mujer considerada bruja al salir a faenar, regresaban a casa por considerar perdido el día. Existen leyendas de viudas y apariciones en la noche de Difuntos. Atractivos: Anfiteatro marinero, puerto.' WHERE codigo_ine='05008' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='En sus montes y acantilados vivían, según la tradición, las meigas. Es uno de los enclaves gallegos donde más persiste la cultura de la brujería costera. Atractivos: Cabo Ortegal, acantilados más altos de Europa, calas.' WHERE codigo_ine='15022' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Cova da Serpe es escenario de una de las leyendas más famosas de Galicia: una serpiente gigante que devoraba ganado y exigía sacrificios hasta que un caballero la venció con una lanza bendita. Atractivos: A Cova da Serpe, torre de San Paio de Narla, mirador natural.' WHERE codigo_ine='27020' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Considerada una de las "ciudades donde viven las brujas de Galicia". Su pasado judío y su posición fronteriza han generado un sustrato de leyendas de apariciones y prácticas esotéricas. Atractivos: Catedral fortificada, barrio judío, Camino Portugués.' WHERE codigo_ine='36014' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Casa de la Sirena, una de las Casas Colgadas, protagoniza una de las leyendas más famosas de la ciudad. El Parador, antiguo convento de San Pablo, acumula relatos de apariciones de monjas. Atractivos: Casas Colgadas, Casa de la Sirena, Parador de Cuenca (antiguo convento).' WHERE codigo_ine='16078' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los pueblos abandonados más impresionantes de España, frecuentado por amantes del misterio y la fotografía de ruinas. Atractivos: Pueblo abandonado, ruinas en lo alto de un cerro a 1.100 metros.' WHERE codigo_ine='16135' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Múltiples apariciones: el espectro de una joven noble vestida de blanco encerrada por su familia tras un amor prohibido; el fantasma de la emperatriz Eugenia de Montijo (última propietaria del castillo en el siglo XIX); y la figura histórica de Juana la Beltraneja. Actores que han rodado en el castillo también han reportado presencias. Atractivos: Castillo de Belmonte (siglo XV, forma de estrella de seis puntas), casco histórico.' WHERE codigo_ine='16033' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Sus cuevas subterráneas, el barrio árabe y su conjunto histórico amurallado son escenario de leyendas y rutas de misterio que recorren sus callejas medievales. Atractivos: Castillo del siglo XV, cuevas del Agujero, barrio árabe.' WHERE codigo_ine='02010' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Posiblemente la ciudad con más rutas de misterio nocturnas de España. Sus calles estrechas y oscuras guardan apariciones reportadas en la Casa de las Cabezas, el Castillo de San Servando y el barrio judío. Existen tours específicos "Toledo Siniestro". Atractivos: Casa de las Cabezas, criptas y momias, Castillo de San Servando, casco antiguo.' WHERE codigo_ine='45168' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Cuna de las célebres "Brujas de Viladrau", perseguidas en el juicio de brujería de 1618-1622. La ermita de Sant Segimon era el punto de reunión de los aquelarres la noche de Todos los Santos. Atractivos: Espai Montseny, ermita de Sant Segimon, macizo del Montseny.' WHERE codigo_ine='17220' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Sede de los juicios por brujería de la Catalunya central. Su museo narra la persecución, tortura y muerte de las mujeres condenadas por brujería, con un montaje multimedia basado en hechos reales. Atractivos: Centre d''Interpretació de la Bruixeria.' WHERE codigo_ine='08212' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Mussara, pedanía despoblada en los años 60, lleva más de 100 años con un misterio sin resolver. Se reportan fenómenos paranormales, apariciones y ruidos inexplicables entre sus ruinas; se ha comparado con el pueblo de "Stranger Things". Atractivos: Pueblo fantasma de La Mussara, Sierra de Prades.' WHERE codigo_ine='43169' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La tradición oral mantiene viva la existencia de brujas en los Ibores, con testimonios recogidos por la Inquisición en la comarca. Es uno de los puntos de brujería documentada de Extremadura. Atractivos: Cueva de Castañar (Monumento Natural), Sierra de Villuercas.' WHERE codigo_ine='10060' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Cueva de las Brujas de Ibahernando es un lugar donde "la imaginación se despierta sola", según los lugareños, asociado a leyendas de aquelarres y rituales. Atractivos: Cueva de las Brujas, casco rural.' WHERE codigo_ine='10102' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El ex-convento de San Francisco en ruinas es uno de los lugares más inquietantes de Extremadura, frecuentado por amantes del turismo oscuro. Atractivos: Ex-Convento abandonado de San Francisco, catedral.' WHERE codigo_ine='10067' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los centros de peregrinación más misteriosos de España. Hasta el siglo XX acudían "endemoniados" para ser exorcizados en el santuario, con testimonios documentados de posesiones y rituales de liberación. Atractivos: Santuario de la Virgen de la Balma (excavado en la roca).' WHERE codigo_ine='12141' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La leyenda de la Vera Cruz (lignum crucis que apareció milagrosamente en 1231) y la tradición templaria del lugar generan una oferta de rutas de misterio ("Caravaca Misteriosa") donde se narra la doble vela a Dios y al Diablo de los caballeros caídos. Atractivos: Santuario de la Vera Cruz, castillo templario, casco histórico.' WHERE codigo_ine='30015' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Isla del Barón, en el Mar Menor, es escenario de la leyenda de una aparición femenina la noche de San Juan. Los pescadores relatan haber visto a una mujer de extraordinaria belleza envuelta en un resplandor. Atractivos: Mar Menor, Isla del Barón.' WHERE codigo_ine='30035' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los castillos más espectaculares de España: un rey de Navarra tuvo como mascota a un león y un fantasma se pasearía por él. Leyendas templarias, símbolos extraños y figuras llenas de misterio se dan cita en sus muros. Atractivos: Castillo de Javier (siglo XI), basílica, museo.' WHERE codigo_ine='31135' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las alas del palacio, hoy Parador, encierra la leyenda de un fantasma noble medieval. Se escuchan ruidos, lamentos y melodías de otros tiempos, especialmente en la Galería Dorada. Varios testimonios avalan el paseo del espectro del rey Carlos III. Atractivos: Palacio Real de Olite (Parador Príncipe de Viana).' WHERE codigo_ine='33013' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Durante la Guerra Civil fue uno de los mayores campos de prisioneros. Murieron unos 750 presos, 231 de ellos en la fuga de mayo de 1938. El lugar es uno de los escenarios de turismo oscuro y parapsicología más visitados del norte. Atractivos: Fuerte de San Cristóbal (monte Ezkaba).' WHERE codigo_ine='90717' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Lugar de la aparición de la Virgen del Pino (8 de septiembre de 1481), patrona de Gran Canaria. La imagen apareció en lo alto de un pino del que brotaba un manantial de aguas medicinales. Es el principal centro de peregrinación mística de la isla. Atractivos: Basílica del Pino, casco histórico, Plaza del Pino.' WHERE codigo_ine='35027' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Leyendas como el "drac de na Coca" (dragón que acechaba en las acequias de la ciudad) y relatos de brujería en el casco antiguo, heredados del pasado musulmán y medieval. Atractivos: Catedral, casco antiguo, barrio de la Calatrava.' WHERE codigo_ine='07040' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los lugares con mayor concentración de energía telúrica del Mediterráneo. Considerado el "tercer vértice del triángulo de las Bermudas" en la tradición esotérica. Leyendas de apariciones, sirenas, templarios y avistamientos de naves no identificadas. Atractivos: Islote rocoso de casi 400 metros al sudoeste de Ibiza, reservas naturales, miradores.' WHERE codigo_ine='15089' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La habitación 712 del Parador es uno de los lugares con fenómenos paranormales más documentados de España. Se escuchan ruidos, lamentos y melodías de otros tiempos. La leyenda atribuye la presencia al espíritu de Adalés, hija del vizconde Ramón Folch, encerrada por su padre en la torre tras enamorarse de un príncipe árabe; murió al año de reclusión. El perro del vigilante nocturno se negaba a pasar por la zona durante las obras de adaptación. Atractivos: Castillo de Cardona (Parador, siglo IX), Colegiata de Sant Vicenç, Torre Minyona.' WHERE codigo_ine='08009' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El Parador de Tortosa, ubicado en un castillo musulmán del siglo X, figura entre los Paradores con mayor misterio de España. Se reportan fenómenos inexplicables, sombras y presencias en sus estancias y en las galerías subterráneas. Atractivos: Castillo de la Zuda (Parador), catedral, casco histórico, murallas.' WHERE codigo_ine='43155' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El fantasma de doña Blanca de Borbón, esposa de Pedro I el Cruel, presuntamente envenenada entre estos muros en 1361. Huéspedes y empleados reportan sollozos, arrastrar de cadenas y una silueta difuminada recorriendo los pasillos abovedados. La Torre de Doña Blanca lleva su nombre. Atractivos: Castillo de Sigüenza (Parador, siglo XII), catedral, casco medieval, Casa del Doncel.' WHERE codigo_ine='19257' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Investigado por el programa Cuarto Milenio (Iker Jiménez y Carmen Porter). Empleadas y huéspedes reportan presencias, sillas que se giran solas y ruidos inexplicables. La habitación 39 es la más activa; varios huéspedes han abandonado el Parador tras vivencias paranormales. Atractivos: Parador de Santa Catalina (antiguo convento), Plaza Mayor, corrales de comedias.' WHERE codigo_ine='13002' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Catedral de León tiene documentados al menos cuatro fantasmas de personajes ilustres. El Parador de San Marcos, antiguo convento-hospital de peregrinos, cárcel (donde estuvo preso Quevedo) y prisión durante la Guerra Civil, es conocido por la aparición del "fantasma de Quevedo" y otras presencias en sus muros renacentistas. Atractivos: Catedral, Hostal de San Marcos (Parador), Casa Botines de Gaudí, Barrio Húmedo.' WHERE codigo_ine='26010' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Según la leyenda local, el espíritu de un noble traicionado y asesinado vaga por las murallas en noches de tormenta, vestido con armadura. Los visitantes reportan susurros y pasos en los pasillos vacíos del castillo. Atractivos: Castillo de Enrique II de Trastámara (Parador), catedral, murallas.' WHERE codigo_ine='37003' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La leyenda del "noble sin cabeza": Fernán Íñiguez de Coca, condenado por traición, vaga por sus pasillos de ladrillo. Se reportan fantasmas y secretos ocultos en sus gruesos muros. Atractivos: Castillo de Coca (siglo XV, gótico-mudéjar), propiedad de la Casa de Alba.' WHERE codigo_ine='40057' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Se dice que algunas noches se ven dos figuras espectrales vagando entre las murallas. La leyenda de Elvira y Roberto, amantes cuya historia terminó en tragedia, es la aparición más reportada; en noches de verano se ven sus sombras bajo una "aureola de fuego". Atractivos: Castillo de Pedraza (siglo XIII), casco medieval, museo de Zuloaga.' WHERE codigo_ine='40156' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Aunque el Parador moderno carece de la carga histórica de otros, la comarca montañesa palentina está llena de leyendas de ojáncanos y tradiciones celtas, y la zona es destino de retiros espirituales. Atractivos: Parador de Cervera de Pisuerga, Reserva Natural de Fuentes Carrionas.' WHERE codigo_ine='34056' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El Castillo de Santiago ha sido investigado por equipos de parapsicología que han documentado fenómenos paranormales (psicofonías, imágenes y testimonios). Se realizan visitas especiales "Fenomenología paranormal en el Castillo de Santiago" donde se proyectan los audios e imágenes captados. Atractivos: Castillo de Santiago (siglo XV), palacios, entrada al Parque de Doñana.' WHERE codigo_ine='11032' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Free tour específico de "Leyendas y Misterios de Ronda" que recorre la Casa Encantada Rúa (espíritu de una niña asesinada que busca venganza), la calle de la Bola, la Casa del 98, la Capilla de los Ajusticiados y la Sauceda. Atractivos: Casa Rúa (Villa Apolo), calle de la Bola, Casa del 98, Capilla de los Ajusticiados, Puente Árabe, La Sauceda, Plaza de la Merced.' WHERE codigo_ine='29084' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Apariciones, ritos prohibidos, crímenes y romances en leyendas no contadas. El Torcal de Antequera tiene un halo de misterio ancestral. La Peña de los Enamorados guarda la leyenda de Tagzona y Tello (los amantes que se lanzaron al vacío). El Dolmen de Menga, 1.000 años más antiguo que Stonehenge, orienta su eje hacia la Peña, enigma arqueológico sin resolver. Atractivos: Dólmenes de Menga y Viera, El Torcal, Peña de los Enamorados, Colegiata de Santa María, casco histórico.' WHERE codigo_ine='32002' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Analizada en el podcast "El Archivo del Misterio" por sus extrañas psicofonías. La Necrópolis romana, con tumbas tan impresionantes como la Tumba del Elefante y la de Servilia, es un foco de actividad paranormal documentada. En 2019 apareció un mausoleo romano en el patio de una vivienda particular. Atractivos: Necrópolis romana, Anfiteatro, Alcázar de la Puerta de Sevilla.' WHERE codigo_ine='41024' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El primer "ghost tour" sobre Cádiz paranormal recoge apariciones en la calle Mesón y el terrible suceso de 1755. Existe el enigma de la "niña" y la investigación de la calle Valcárcel, donde se sucedieron hechos luctuosos que propiciaron fenómenos insólitos. Atractivos: Castillo de Santa Catalina, casco histórico, calle Mesón.' WHERE codigo_ine='16009' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Visitado por Iker Jiménez en busca de sucesos paranormales. Los vecinos mayores recuerdan la aparición de un fantasma en los tejados del castillo zafrense en varias ocasiones a lo largo de los años. Atractivos: Castillo-Palacio de los Duques de Feria (Parador, siglo XII), casco histórico.' WHERE codigo_ine='06023' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los lugares embrujados más famosos de la Comunidad Valenciana. Se han grabado múltiples psicofonías; los investigadores reportan lamentos de niños, rituales, pentagramas y un estruendo impresionante captado al poner un micrófono en el suelo. Investigado por Más Vale Sábado. Atractivos: Psiquiátrico abandonado "La Humanitat" (construido 1960-1980, cerrado en 2000).' WHERE codigo_ine='46109' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Considerada "la isla más paranormal de España". Lugar de aislamiento que acumula psicofonías aterradoras, sombras que se mueven entre las ruinas y el espectro de una misteriosa anciana con bata blanca. Numerosos investigadores han documentado actividad. Atractivos: Antiguo sanatorio infantil de tuberculosis (isla en la bahía de Santander).' WHERE codigo_ine='39040' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Tres presencias documentadas: Margarita de Eguilior (de 29 años, que toca el piano y pasea por las escaleras), su hija, y Antonio (antiguo sirviente). Predilección por la habitación 205. Se han obtenido fotografías con el rostro del Conde de Albox y de "Rosita" sosteniendo un bebé. Atractivos: Parador de Limpias (palacete modernista de principios del siglo XX), Castañar.' WHERE codigo_ine='39038' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El Castillo de San Telmo es uno de los relatos de fantasmas más conocidos de Gipuzkoa. El Parador acumula testimonios de presencias en sus muros con heridas de bala de cañón. Atractivos: Parador de Hondarribia (Castillo de Carlos V, s. X), Plaza de Armas, Castillo de San Telmo.' WHERE codigo_ine='21011' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Leyenda de la princesa mora cautiva que esperó en vano a su caballero y murió prisionera. Su espíritu vaga por los pasillos. El castillo tiene vínculos esotéricos documentados. Atractivos: Castillo de Butrón (siglo XIII, estética de cuento de hadas).' WHERE codigo_ine='90689' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Ligado a Eugenia de Montijo (emperatriz de Francia). Existe una "leyenda negra" que envuelve al castillo, frecuentado por amantes de lo esotérico. Atractivos: Castillo de Arteaga (siglo XIII, neogótico), Reserva de la Biosfera de Urdaibai.' WHERE codigo_ine='48041' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El monasterio alberga restos arqueológicos de la estructura original y siglos de historia benedictina. Es uno de los Paradores con más testimonios de presencias. Atractivos: Parador de Corias (Monasterio de San Juan Bautista, siglo XI, "El Escorial de Asturias"), biblioteca monumental.' WHERE codigo_ine='05006' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Leyenda de Don Pelayo, que murió enfrentándose a un oso en estos bosques. Los huéspedes reportan hojas que se mueven "por un viento que no existe" y la leyenda del oso. Atractivos: Parador de Cangas de Onís (monasterio de San Pedro de Villanueva, siglo VIII), puentes, Covadonga.' WHERE codigo_ine='05005' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Torre del Príncipe inspiró a Alejandro Dumas para El hombre de la máscara de hierro. Leyendas de amantes prohibidos encerrados, del príncipe portugués Alfonso Enríquez y del Conde de Gondomar. Atractivos: Parador de Baiona (Castillo de Monterreal, fortaleza de 3 km de perímetro amurallado), Torre del Príncipe.' WHERE codigo_ine='36002' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El Parador, antiguo hospital de peregrinos, acumula leyendas de peregrinos fallecidos, apariciones marianas y meigas. Conxo, hospital psiquiátrico desde 1885 con más de 1.200 pacientes en condiciones deplorables, icono del turismo oscuro gallego. Atractivos: Hostal de los Reyes Católicos (Parador, s. XV), Catedral, casco viejo, Hospital Psiquiátrico de Conxo.' WHERE codigo_ine='15078' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El actual propietario asegura que el fantasma de la primera propietaria de la casa ronda las estancias, especialmente en determinadas fechas. La casa tiene capilla privada y mobiliario antiguo intacto. Atractivos: Casa Bardaxí (Plaza Mayor, siglo XVII), casco histórico ribagorzano.' WHERE codigo_ine='22117' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El milagro del gallo y la gallina: un joven peregrino alemán, Hugonell, fue injustamente ahorcado y, cuando sus padres fueron a buscarlo, este seguía vivo milagrosamente mientras un gallo asado cantaba. Es Bien de Interés Cultural inmaterial y uno de los misterios más famosos del Camino. Atractivos: Catedral,朝圣之路, mesón tradicional.' WHERE codigo_ine='26138' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La tradición oral alpujarreña conserva leyendas de brujería heredadas de la repoblación con gallegos (que trajeron el culto a las meigas), rituales de fertilidad y apariciones en los barrancos. Atractivos: Barranco del Poqueira, pueblos blancos de la Alpujarra.' WHERE codigo_ine='18151' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La "Vieja del Blanqueo" forma parte de la tradición oral del municipio, vinculada a la antigua fábrica de blanqueo de papel (dirigida por Berta Wilhelmi) y al patrimonio industrial abandonado de la zona. Las ruinas de la fábrica y los paseos de la central eléctrica (incluidos en rutas como "Los Misterios de Pinos Genil" de Secretos de Granada) generan relatos de presencias y ecos del pasado industrial. La documentación escrita sobre la aparición es escasa, por lo que se mantiene como leyenda oral local. Atractivos: Antigua Fábrica del Blanqueo de papel (s. XIX, hoy Centro CREA), Fábrica de la Luz, Presa de Pinillos, Pantano de Canales, Centro de Interpretación del Tranvía de la Sierra.' WHERE codigo_ine='18157' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Lugar del fusilamiento de Federico García Lorca (agosto 1936). La Fuente Grande, manantial árabe que abastecía la Alhambra, es uno de los últimos reductos musulmanes en capitular (1491). El entorno está cargado de la energía del Barranco de Víznar y de la "no-muerte" de Lorca (leyenda del panadero que lo encontró malherido). Atractivos: Fuente Grande o de las Lágrimas (Aynadamar), Parque Federico García Lorca, Sierra de la Alfaguara.' WHERE codigo_ine='90429' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Más de 6.500 personas enterradas en fosas comunes en el barranco. Las exhumaciones continúan. Es uno de los escenarios de turismo oscuro más simbólicos de España. Atractivos: Palacio del Cuzco (sede de la represión en 1936), Barranco de Víznar (Lugar de Memoria).' WHERE codigo_ine='18189' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El hombre sin rostro de la Casa Cervantes. Testigos han visto una figura etérea masculina sin rostro que vaga y desaparece. La historia trágica: hace más de 200 años un hombre cayó al pozo del patio, murió ahogado y su rostro quedó tan deformado que lo taparon con una sábana. También se reportan avistamientos OVNI y procesos de la Inquisición. Atractivos: Casa de Cervantes (s. XVI), barrio de La Villa, Palacio de Beniel.' WHERE codigo_ine='29094' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Trompetas del Apocalipsis y caso de ouija con intervención de la Policía Nacional. Dos mujeres y una menor se comunicaron con el espíritu de un niño llamado Agustín (patrón de la ciudad); cuadros y radiadores se movían solos. La situación fue tan alarmante que requirió la intervención policial. Atractivos: Casco histórico minero, Castillo de Tobaruela, plaza de Toros.' WHERE codigo_ine='23055' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Maldición del callejón de las Brujas. María Santiago Rabadán, juzgada por hechicería en un Auto de Fe en 1655. Investigado por Manuel Jesús Segado Uceda. Atractivos: Casco histórico, callejón de las Brujas, restos romanos.' WHERE codigo_ine='24006' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Leyenda del Señor de las Cadenas, la Dama de la Capa y el origen de la expresión "irse por los cerros de Úbeda". La Puerta de Granada oculta un tesoro medieval junto a la muralla árabe. La Casa de los Salvajes acumula relatos inquietantes. Atractivos: Casco renacentista (Patrimonio UNESCO), Capilla del Salvador, Casa de los Salvajes, Plazuela, Sinagoga del Agua, Puerta de Granada.' WHERE codigo_ine='23092' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Pueblos del norte de Jaén unidos por una historia de magia y misterio, exvotos íberos y poemas de Jorge Manrique. Atractivos: Cueva de la Lobera, santuario ibérico de los Altos del Sotillo, puente romano sobre el Guadalimar.' WHERE codigo_ine='23029' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Dama Blanca que aparece sentada en noches de tormenta en la carretera Casar de Cáceres-Arroyo de la Luz. Es una de las apariciones en cunetas extremeñas más conocidas. Atractivos: Carreteras comarcales de Extremadura.' WHERE codigo_ine='10049' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El hombre alto vestido de negro que continúa suicidándose en la curva de Mirabel. Una de las apariciones de carretera más escalofriantes de Extremadura. Atractivos: Carretera de la curva de Mirabel.' WHERE codigo_ine='10123' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La dama de rojo de Miajadas, aparición en cuneta. Atractivos: Cruce de carreteras en la Serena.' WHERE codigo_ine='10121' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La niña vestida de comunión que se acerca a los coches en la carretera de Peraleda de la Mata. Atractivos: Carretera local junto al embalse de Orellana.' WHERE codigo_ine='10140' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La joven de la recta de la carretera Montehermoso-Pozuelo de Zarzón. Atractivos: Carretera de la Sierra de Gata.' WHERE codigo_ine='10127' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El misterio del reloj maldito y el pueblo poseído por el diablo. Un extraño suceso con el reloj del pueblo desencadenó una serie de muertes misteriosas. Inspiró el libro "La rebelión de Lucifer" de J.J. Benítez. Recogido por el programa Palacios y Castillos con Misterio de CyLTV. Atractivos: Iglesia, torre del reloj del pueblo, Sierra de Albarracín.' WHERE codigo_ine='42174' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El fantasma de Masegoso. El pueblo, rico y floreciente, desapareció tras el odio irreconciliable entre dos poderosas familias (Julián Alvarez y Andrés Orozco). Leyenda de desaparición misteriosa de un pueblo entero. Atractivos: Torre de Masegoso, paisaje serrano.' WHERE codigo_ine='02047' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La antigua Bletisa romana acumula leyendas medievales entre sus calles y murallas, en una de las zonas más mágicas de la provincia. Atractivos: Conjunto Histórico-Artístico, castillo, ribera del Tormes, Arribes.' WHERE codigo_ine='37006' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Pueblo de montaña con tradiciones y leyendas ancestrales, en una de las sierras más mágicas de Salamanca. Atractivos: Sierra de Candelario, arquitectura tradicional.' WHERE codigo_ine='37001' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Cabecera de la comarca de Sanabria, tierra de meigas, conjuros, mal de ojo y el "llobu". Cerca del Lago de Sanabria con su leyenda de Valverde de Lucerna (pueblo sumergido cuyas campanas suenan la noche de San Juan). Atractivos: Villa medieval amurallada, castillo de los Condes de Benavente, río Tera.' WHERE codigo_ine='49166' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Cuenta con ruta nocturna oficial "Mitos y Leyendas" organizada por el Ayuntamiento, que recorre los secretos que esconde la villa cuando cae la noche. Atractivos: Villa medieval, Arribes del Duero, bodegas subterráneas.' WHERE codigo_ine='49065' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El misterio de la Calle Balborraz: un capitán musulmán que quería destruir la ciudad, una ejecución y una historia de amor. Se cruza con la leyenda de la "Cabeza de Piedra" de la Catedral. Atractivos: Colegiata, cimborrio, casco histórico, ribera del Duero.' WHERE codigo_ine='49219' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Acoge las Jornadas de Misterio y acumula leyendas como la más oscura de la provincia. La Catedral y la iglesia de San Pedro y San Ildefonso concentran relatos de apariciones. Atractivos: Catedral, conjunto románico, puente sobre el Duero, iglesias.' WHERE codigo_ine='49275' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='El misterio del fauno burgalés: en el Jardín Secreto se esconde la escultura de un fauno petrificado por una maldición, guardian de los seres mágicos del bosque. Entrada libre. Atractivos: Monasterio de San Salvador, Jardín Secreto, Casa del Parque Montes Obarenes.' WHERE codigo_ine='09011' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las ciudades más pequeñas de España, con un castillo que acumula leyendas desde el siglo X. Atractivos: Ciudad colgante sobre La Muela, castillo del siglo X, iglesia fortificada de San Vicente.' WHERE codigo_ine='09007' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las Raíces de Castilla, con un patrimonio cargado de historia y leyendas en el norte de Burgos. Atractivos: Salinas romanas, pueblo natal de Félix Rodríguez de la Fuente.' WHERE codigo_ine='09014' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Villa ducal con un pasado cargado de intrigas palaciegas y leyendas entre sus conventos. Atractivos: Ducado de Lerma, conventos, plaza mayor.' WHERE codigo_ine='09008' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las Raíces de Castilla, con un casco histórico que guarda leyendas desde los orígenes del condado. Atractivos: Colegiata, casco medieval, origen de Castilla.' WHERE codigo_ine='09005' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La Dama de la Mota y la maldición del castillo. La reina Isabel lo utilizó como residencia y prisión política; varios personajes fueron ejecutados por mandato real entre sus muros. Es uno de los castillos más temidos de Castilla. Atractivos: Castillo de la Mota (siglo XIII), casco histórico, Plaza Mayor.' WHERE codigo_ine='47085' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los municipios palentinos que más misterios alberga: se habla de energías milenarias, una sociedad intraterrestre y avistamiento de objetos luminosos no identificados en el cielo. Considerado "lugar de poder". Atractivos: Casco urbano, entorno natural.' WHERE codigo_ine='90805' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La leyenda dice que Plinio el Viejo mencionó estas fuentes. La zona está cargada de historia y tradiciones ancestrales. Atractivos: Fuentes romanas de La Reana (más de 2000 años), embalse de Camporredondo.' WHERE codigo_ine='34199' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Ruta "Palencia Misteriosa" de Rutas Misteriosas: episodios paranormales en la Catedral, la Diputación y el antiguo orfanato de Huérfanos Ferroviarios. Viejas leyendas de crímenes sin resolver, desapariciones y el Cristo que desvía los rayos en las tormentas. Atractivos: Catedral de San Antolín ("La Bella Desconocida"), Cristo del Buen Suceso, calle Mayor.' WHERE codigo_ine='34120' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Peñasco estratégico con un casco histórico cargado de leyendas medievales, en uno de los pueblos más singulares de la provincia de Cuenca. Atractivos: Villa medieval amurallada sobre un meandro del Júcar, castillo, iglesia fortificada.' WHERE codigo_ine='14001' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Antigua ciudad romana y medieval, con un patrimonio cargado de leyendas y tradiciones. Atractivos: Conjunto histórico, cuatro museos (Arte Sacro, Fragua, Etnográfico, Florencio de la Fuente).' WHERE codigo_ine='16112' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los pueblos más bonitos de la provincia, en un paraje natural escénico que acumula tradiciones y leyendas. Atractivos: Estrecho de Priego (hoz del río Escabas), casco histórico de la Alcarria conquense.' WHERE codigo_ine='16170' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='En el corazón de la Alcarria, Pastrana ofrece "historia, conventos y leyendas" del Siglo de Oro, con la figura maldita de la princesa de Éboli. Atractivos: Palacio de la princesa de Éboli, conventos de Carmelitas, plaza Mayor.' WHERE codigo_ine='19212' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Villa medieval con un patrimonio cargado de leyendas de caballeros y tradiciones ancestrales. Atractivos: Castillo, casco medieval, Caballeros de Atienza.' WHERE codigo_ine='19044' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Enclave brujeril documentado. Las brujas de Molina se trasladaban hipotéticamente hasta Gallocanta (Zaragoza) para un aquelarre. Una tal Águeda, del siglo XVI, declaró que su abuela había sido bruja y se reunía en Gallocanta. Atractivos: Castillo, Señorío de Molina, casco histórico.' WHERE codigo_ine='19190' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Objeto del libro "Alcarria bruja. Historia de la hechicería en Guadalajara y los procesos de la villa de Pareja", de Javier Fernández Ortea. Procesos de brujería documentados. Atractivos: Casco urbano de la Alcarria, embalse de Entrepeñas.' WHERE codigo_ine='19211' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Acumula leyendas y tradiciones populares de la provincia de Toledo, con un sustrato de misterios recogidos por José Talavera. Atractivos: Casco histórico, cerámica, río Tajo, murallas.' WHERE codigo_ine='45165' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Zona conocida por las leyendas de los monjes sobrenaturales, recogidas en el libro de mitos y leyendas de Castilla-La Mancha. Atractivos: Puerto de los Yébenos, Montes de Toledo.' WHERE codigo_ine='45200' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Las minas de Almadén son escenario de la leyenda del Morgo, duende minero que extrae minerales bajo tierra. Tradiciones de brujería y apariciones en una de las comarcas más enigmáticas de CLM. Atractivos: Minas de mercurio (Patrimonio UNESCO), hospital de mineros, plaza de toros.' WHERE codigo_ine='90825' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Cuenta con leyendas de fantasmas locales, recogidas en rutas y tradiciones orales. Atractivos: Casco histórico, museos mineros.' WHERE codigo_ine='13013' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='La mano negra, el morgo y los fantasmas de Valdepeñas son algunos de sus mitos y leyendas más conocidos. Atractivos: Bodegas, plaza Mayor, museo del vino.' WHERE codigo_ine='13018' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los pueblos con castillo más impresionantes de Albacete, con historia y leyendas de la Sierra del Segura. Atractivos: Castillo de Yeste, Sierra del Segura, casco histórico.' WHERE codigo_ine='02030' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Una de las fortalezas más impresionantes de Albacete, con historia y leyendas asociadas a la famosa batalla. Atractivos: Castillo de Almansa (siglo XIV), casco histórico.' WHERE codigo_ine='02005' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Uno de los pueblos más bonitos de Albacete, con historia medieval y leyendas. Atractivos: Plaza Mayor, torres del Salvador y de la Alcadima, casco histórico.' WHERE codigo_ine='02004' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Centro de aquelarres de toda Aragón. Las brujas de la zona se reunían en la laguna, con leyendas de hechicería que recorren la zona desde hace siglos. Las brujas de Molina de Aragón se desplazaban hasta aquí. Atractivos: Laguna de Gallocanta (mayor laguna salada de Europa), observatorio de grullas.' WHERE codigo_ine='50117' AND fuente='inventario_misterioso_pdf';
UPDATE entidades SET descripcion='Comparte nombre con Rubielos de Mora por una leyenda de amor que explica por qué ambos pueblos tienen el mismo nombre invertido. Atractivos: Castillo de Mora, casco histórico, Sierra de Gúdar.' WHERE codigo_ine='44158' AND fuente='inventario_misterioso_pdf';
